		t.Parallel()
		summary := trailRunsSummary(
			textRun("claude-code", "approve\n"+emptyTrailJSON),
			textRun("codex", "approve — looks fine"),
		)
		report, called, _ := postedTrailReport(t, summary, "")
		requirePostedProse(t, report, called, "## codex")
	})

